 NativeHudFrame(NativeSceneSnapshot scene){if(scene==null)throw new IllegalArgumentException("Historical HUD scene required");ByteBuffer c=ByteBuffer.allocateDirect(153600).order(ByteOrder.LITTLE_ENDIAN),m=ByteBuffer.allocateDirect(153600).order(ByteOrder.LITTLE_ENDIAN);byte[] vram=new byte[98304],palette=new byte[1024],oam=new byte[1024];for(int y=0;y<160;y++){ByteBuffer row=scene.row(y);int display=row.getShort(8)&65535,blend=row.getShort(8+0x50)&65535,alpha=row.getShort(8+0x52)&65535,brightness=row.getShort(8+0x54)&65535;if((display&0x8080)!=0||(display&7)!=4)throw new IllegalArgumentException("Unsupported historical HUD row");int[] window=new int[6];for(int i=0;i<6;i++)window[i]=row.getShort(8+64+i*2)&65535;row.position(128);row.get(vram).get(palette).get(oam);NativeHudCandidates.Row prepared=NativeHudCandidates.prepare(vram,palette,oam,display,y,window,blend,brightness);int[] pixels=prepared.colors(),tags=prepared.tags();byte[] visible=prepared.visible(),backdrop=prepared.backdrop();for(int x=0;x<240;x++){int control=visible[x]&255;if((display&0x400)==0)control&=~4;int flags=128|control|((backdrop[x]&32)!=0?64:0);c.putInt(pixels[x]);m.putInt(0xff000000|(flags<<16)|(tags[x]&3)|(((tags[x]>>>2)&3)<<8));}int color=(palette[0]&255)|((palette[1]&255)<<8);parameters[y]=new int[]{rgb(color),row.getShort(8+12)&3,blend,alpha,brightness};}c.position(0);m.position(0);colors=c.asReadOnlyBuffer().order(ByteOrder.LITTLE_ENDIAN);metadata=m.asReadOnlyBuffer().order(ByteOrder.LITTLE_ENDIAN);}
